class Base {
    int v_;
public:
    Base() : v_(0) {}
    explicit Base(int v) : v_(v) {}
};

template <typename T>
class Derived : public Base {
    T payload;
public:
    // Inherit Base's constructors
    using Base::Base;

    // Template specific constructor
    Derived(T p) : payload(p) {}
};
